});


async function addFlowRoads (viewer) {
  const geojson = await fetch('/data/roads.geojson').then(res => res.json());
  const features = geojson.features;

  const instances = [];
  for (let f of features) {
    const coords = f.geometry.coordinates;
    const flat = coords.flat();
    const positions = Cesium.Cartesian3.fromDegreesArray(flat);

    const geometry = new Cesium.PolylineGeometry({
      positions,
      width: 2,
      vertexFormat: Cesium.PolylineMaterialAppearance.VERTEX_FORMAT
    });

    const instance = new Cesium.GeometryInstance({ geometry });
    instances.push(instance);
  }

  const material = new Cesium.Material({
    fabric: {
      type: 'Spriteline1',
      uniforms: {
        color: Cesium.Color.CYAN,
        image: '/images/资源 1.png',
        time: 0
      },
      source: Cesium.Material.Spriteline1Source
    }
  });

  const primitive = new Cesium.Primitive({
    geometryInstances: instances,
    appearance: new Cesium.PolylineMaterialAppearance({
      material,
      flat: true
    })
  });

  viewer.scene.primitives.add(primitive);

  // 动态更新时间
  viewer.clock.onTick.addEventListener(clock => {
    const start = Cesium.JulianDate.toDate(viewer.clock.startTime).getTime();
    const now = Cesium.JulianDate.toDate(clock.currentTime).getTime();
    material.uniforms.time = ((now - start) / 1000) % 1;
  });
}

